<script setup>
import {analytics} from '../analytics.js'
import { computed, inject, onMounted, ref, watch } from 'vue'
import EvidenceDetails from '../components/EvidenceDetails.vue'
import InterviewPractice from '../components/InterviewPractice.vue'
import CareerProjectPrompt from '../components/CareerProjectPrompt.vue'
import WorkspaceDrawer from '../components/WorkspaceDrawer.vue'
const career=inject('career'),work=inject('workspace'),{state}=career
const rag=inject('retrieval'),mode=inject('experimentMode'),practice=inject('practice')
const legacyOpen=ref(false)
const activeExperiment=computed(()=>mode.value==='RETRIEVAL'?rag.state:work.state)
const restoring=ref(true)
const editKey=ref(''),editText=ref(''),notice=ref('')
const focus=ref('EVALUATION_WORKBENCH'),target=ref('AI_EVALUATION_PLATFORM_PM'),speechRate=ref(240),judgments=ref({}),judgmentsConfirmed=ref(false),exportGroup=ref('')
const options=()=>({project_focus:focus.value,career_target:target.value,speech_rate:Number(speechRate.value),completions:Object.entries(judgments.value).filter(([k,v])=>v?.trim()).map(([field,text])=>({field,text,evidence_state:field==='root_cause'?'INFERENCE':'USER_CONFIRMED',temporal_scope:'RETROSPECTIVE',confirmed:true}))})
watch(()=>state.view,v=>{if(v){focus.value=v.project_focus;target.value=v.career_target;judgments.value=Object.fromEntries((v.completions||[]).map(c=>[c.field,c.text]));judgmentsConfirmed.value=!!v.completions?.length}})
async function inspect(){await career.preview({project_focus:focus.value,career_target:target.value})}
async function generate(){if(Object.values(judgments.value).some(v=>v?.trim())&&!judgmentsConfirmed.value){analytics.blocked('career.generate','unconfirmed');notice.value='请确认补充判断属实，根因只作为待验证假设保存。';return}await career.generateV2(options())}
const tabs=['Evidence','Case Study','Resume','Interview','Defense']
onMounted(async()=>{try{await career.restore()}catch{notice.value='材料入口暂时无法恢复，请从历史记录重试。'}finally{restoring.value=false}})
const selected=computed(()=>career.selection())
async function organize(){await career.build(null,'PROJECT_TEMPLATE')}
const verified=computed(()=>state.evidence?.claims.filter(c=>['RECORDED','DERIVED','USER_CONFIRMED'].includes(c.confidence))||[])
const resumeClaims=id=>state.evidence?.claims.filter(c=>id.includes(c.claim_id))||[]
function begin(group,s){editKey.value=group+':'+s.section_id;editText.value=s.text}
async function save(group,s){await career.edit(group,s.section_id,editText.value);editKey.value=''}
async function copy(){try{const data=await career.export(exportGroup.value||null);await navigator.clipboard.writeText(data.markdown);void analytics.event('export_copy');analytics.record('copy_success',{action:'career.copy',placement:'CareerPage.control_21',material:({case_study:'project',resume_ai:'resume',resume_general:'resume',interview:'interview',defense:'interview'})[exportGroup.value]||'all'});notice.value='Markdown 已复制'}catch{notice.value='复制失败，请使用导出 Markdown'}}
async function download(){const data=await career.export(exportGroup.value||null);const blob=new Blob([data.markdown],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=data.filename;a.click();URL.revokeObjectURL(url);void analytics.event('export_download');analytics.record('download_trigger',{action:'career.download',placement:'CareerPage.control_22',material:({case_study:'project',resume_ai:'resume',resume_general:'resume',interview:'interview',defense:'interview'})[exportGroup.value]||'all'});notice.value='Markdown 已导出'}
const groups=computed(()=>state.tab==='Case Study'?['case_study']:state.tab==='Resume'?['resume_ai','resume_general']:state.tab==='Interview'?['interview']:[])
const dimensionLabels={completeness:'叙事完整性',evidence_integrity:'事实可追溯性',ownership_clarity:'个人贡献边界',metric_literacy:'指标口径',decision_depth:'决策依据',interview_clarity:'口述清晰度',followup_resilience:'深入追问准备'}
const statusLabels={READY:'已具备',NEEDS_INPUT:'待本人补充',NEEDS_VERIFICATION:'待验证',DRAFT:'草稿'}
const heading={resume_ai:'AI 产品版',resume_general:'通用产品版',case_study:'项目复盘',interview:'面试口述'}
</script>
<template>
 <CareerProjectPrompt :kind="mode" :experiment="activeExperiment" :evidence="state.evidence" :career-view="state.view" :conclusions="practice.state.conclusions" :busy="!!work.state.busy" @history="legacyOpen=true" @evaluate="work.go('evaluate')" />
 <WorkspaceDrawer :open="legacyOpen" title="历史项目材料" @close="legacyOpen=false">
 <div class="page-heading"><div><p class="eyebrow">EVIDENCE → CAREER</p><h1>把做过的实验，说清楚。</h1><p>按项目的固定背景和你已完成的操作，整理产品判断、实验结果与求职材料。</p></div></div>
 <section class="panel"><h2>选择当前实验的证据</h2><p>{{selected.experiment_type==='RETRIEVAL'?'RAG 检索实验':'Agent 行为实验'}} · Baseline {{selected.baseline_run_id || '尚未选择'}} · {{selected.comparison_id?'已有对比':'尚无对比，只能生成事实草稿'}}</p>
  <button v-track="{action:'career.evidence',placement:'CareerPage.control_01',core:true,reason:(restoring || work.state.busy ? 'busy' : 'baseline')}" class="primary" :disabled="restoring || !selected.baseline_run_id || !!work.state.busy" @click="organize">根据操作记录整理项目</button>
  <p class="muted">自动使用固定项目背景与“产品设计”角色，从本次记录提取主要工作，不需要再填写背景表。继续实验后可重新整理，旧材料仍保留。</p>
  <details><summary v-track="{action:'career.history',placement:'CareerPage.control_02'}">打开历史证据 / 材料</summary><div class="button-row"><button v-track="{action:'career.open_evidence',placement:'CareerPage.control_03'}" v-for="e in state.evidenceHistory" :key="e.evidence_object_id" class="secondary" :disabled="!!work.state.busy" @click="career.openEvidence(e.evidence_object_id)">{{e.project_name}} · Evidence v{{e.evidence_version}}</button><button v-track="{action:'career.open_history',placement:'CareerPage.control_04'}" v-for="m in state.materialHistory" :key="m.material_id" class="secondary" :disabled="!!work.state.busy" @click="career.openMaterial(m.material_id)">材料 v{{m.material_version}} · {{m.label}} · Evidence v{{m.evidence_version}}</button></div></details>
 </section>
 <template v-if="state.evidence">
  <nav class="button-row career-tabs" aria-label="材料类型"><button v-track="{action:'career.open',placement:'CareerPage.control_05',material:({'Case Study':'project',Resume:'resume',Interview:'interview',Defense:'interview',Evidence:'evidence'})[t],viewed:!!state.material}" v-for="t in tabs" :key="t" :class="state.tab===t?'primary':'secondary'" @click="state.tab=t">{{t}}</button></nav>
  <p class="note">锁定 Evidence v{{state.evidence.evidence_version}} · {{state.material?.label || 'Draft'}}。Evidence-backed 表示陈述有记录来源，不代表因果证明或商业验证。</p>
  <template v-if="state.tab==='Evidence'">
   <div class="intro-cards"><section><h3>有来源的事实</h3><strong>{{verified.length}}</strong></section><section><h3>不能证明什么</h3><strong>{{state.evidence.limitations.length}}</strong></section><section><h3>待补充</h3><strong>{{state.evidence.missing_evidence.length}}</strong></section></div>
   <section class="panel"><h2>我能安全说什么</h2><ul><li v-for="c in state.evidence.claims.filter(c=>c.allowed_for_resume)" :key="c.claim_id">{{c.claim_text}} <small>· {{c.source_type}}</small></li></ul><details><summary v-track="{action:'career.sources',placement:'CareerPage.control_06'}">全部事实与来源</summary><div v-for="c in state.evidence.claims" :key="c.claim_id" class="builder-card"><p>{{c.claim_text}} · {{c.source_type}}</p><EvidenceDetails data-analytics-location="CareerPage.EvidenceDetails.1" :data="c" title="Claim 证据路径" /></div></details></section>
   <section class="panel"><h2>我不能证明什么</h2><ul><li v-for="l in state.evidence.limitations" :key="l">{{l}}</li></ul><h3>退化与无效结果</h3><p>退化 Case：{{state.evidence.regressions.length}}；无效 / 缺失记录：{{state.evidence.invalid_cases.length}}</p><p v-for="r in state.evidence.regressions" :key="r.case_id">{{r.case_id}} · {{r.transition || r.effective_transition}}</p><p v-for="r in state.evidence.invalid_cases" :key="r.run_id+r.case_id+r.category">{{r.case_id}} · {{r.category}}</p></section>
   <section class="panel" v-if="state.evidence.context"><h2>已整理的项目背景与个人工作</h2><p>背景来自项目设定，个人工作来自本次保存的操作记录。平台完成的工作会单独说明。</p><dl><dt>目标用户</dt><dd>{{state.evidence.context.target_users}}</dd><dt>要解决的问题</dt><dd>{{state.evidence.context.user_problem}}</dd><dt>我的角色</dt><dd>{{state.evidence.context.user_roles.join('、')}}</dd><dt>本次主要工作</dt><dd>{{state.evidence.context.user_contribution}}</dd></dl><details><summary>查看项目背景、技术用途与协作分工</summary><p>{{state.evidence.context.motivation}}</p><p>{{state.evidence.context.why_ai}}</p><p>{{state.evidence.context.system_contribution}}</p><p>{{state.evidence.context.existing_capabilities}}</p></details><p class="muted">18–24 岁求职者是这个实践工作台的用户；实验中模拟的电商客服服务购物者，两者的场景会分开说明。</p></section>
   <EvidenceDetails data-analytics-location="CareerPage.EvidenceDetails.2" :data="{hash:state.evidence.evidence_hash,source_map:state.evidence.source_map}" title="高级 Evidence Source / Fact Lock" />
  </template>
  <section class="panel" v-if="state.evidence.context"><h2>选择叙事主线与求职定位</h2><p>新材料使用当前锁定证据和所选叙事。旧材料仍可从历史记录打开，不会被覆盖。生成过程不调用收费模型。</p>
   <div class="form-row"><label>项目主线<select v-track="{action:'career.focus',placement:'CareerPage.control_14'}" v-model="focus"><option value="EVALUATION_WORKBENCH">Agent 评测与优化工作台</option><option value="CUSTOMER_SERVICE_APP">电商客服应用（背景不足时标缺口）</option></select></label><label>求职定位<select v-track="{action:'career.target',placement:'CareerPage.control_15'}" v-model="target"><option value="AI_EVALUATION_PLATFORM_PM">AI 评测 / 平台产品经理</option><option value="AI_APPLICATION_PM">AI 应用产品经理</option><option value="GENERAL_PM">通用产品经理</option></select></label><label>口述语速（单位 / 分钟）<input v-track="{action:'careerpage.edit_start',placement:'CareerPage.editor',kind:'edit'}" v-model="speechRate" type="number" min="180" max="300" /></label></div>
   <button v-track="{action:'career.preview',placement:'CareerPage.control_16',core:true,reason:('busy')}" class="secondary" :disabled="!!work.state.busy" @click="inspect">检查证据与待补判断</button>
   <details v-if="state.view"><summary>可选：补充记录里没有的个人判断</summary><p>已有修改理由和已确认反思会复用。补充内容单独保存，不改原实验；根因始终标为待验证假设。</p><p v-if="!state.view.missing_questions.length">当前没有需要补充的判断。</p>
   <label v-for="q in state.view.missing_questions.filter(q=>q.field!=='app_context')" :key="q.field">{{q.question}}<textarea v-track="{action:'careerpage.edit_start',placement:'CareerPage.editor',kind:'edit'}" v-model="judgments[q.field]" rows="3" /></label><p v-for="q in state.view.missing_questions.filter(q=>q.field==='app_context')" :key="q.field" class="note warning">{{q.question}}</p>
   <details v-if="state.view.completions.length"><summary v-track="{action:'career.judgments',placement:'CareerPage.control_17'}">已保存的补充判断</summary><p v-for="c in state.view.completions" :key="c.field">{{c.field}} · {{c.evidence_state}} · {{c.text}}</p></details>
   <label class="check" v-if="Object.values(judgments).some(v=>v?.trim())"><input v-track="{action:'career.confirm_judgments',placement:'CareerPage.control_18'}" type="checkbox" v-model="judgmentsConfirmed" />我确认这些是本人补充的判断；根因尚待验证</label></details>
  </section>
  <section class="panel"><div class="button-row"><button v-track="{action:'career.generate',placement:'CareerPage.control_19',core:true,reason:(work.state.busy ? 'busy' : 'unconfirmed')}" class="primary" :disabled="!state.evidence.context || !!work.state.busy" @click="generate">基于此 Evidence 生成全套材料</button><label v-if="state.material?.view_id">导出范围<select v-track="{action:'career.export_group',placement:'CareerPage.control_20'}" aria-label="导出范围" v-model="exportGroup"><option value="">全套材料</option><option value="case_study">项目复盘</option><option value="resume_ai">AI PM 简历</option><option value="resume_general">通用 PM 简历</option><option value="interview">面试讲稿</option><option value="defense">追问证据卡</option></select></label><button v-track="{action:'career.copy',placement:'CareerPage.control_21',material:({case_study:'project',resume_ai:'resume',resume_general:'resume',interview:'interview',defense:'interview'})[exportGroup] || 'all'}" v-if="state.material" class="secondary" @click="copy">复制 Markdown</button><button v-track="{action:'career.download',placement:'CareerPage.control_22',material:({case_study:'project',resume_ai:'resume',resume_general:'resume',interview:'interview',defense:'interview'})[exportGroup] || 'all'}" v-if="state.material" class="secondary" @click="download">导出 Markdown</button></div><p v-if="notice" role="status">{{notice}}</p><p v-if="!state.evidence.context">点击上方“根据操作记录整理项目”，即可使用固定背景生成材料。</p></section>
  <template v-if="state.material">
   <section class="panel" v-if="state.material.view_id"><h2>面试材料准备度</h2><p>这是材料内部完整性检查，不预测面试通过率。Draft 可以导出，但应保留待补充标记。</p><details v-for="(checks,name) in state.material.readiness" :key="name"><summary v-track="{action:'career.readiness',placement:'CareerPage.control_23'}">{{heading[name]||'追问证据卡'}}</summary><p v-for="(check,key) in checks" :key="key">{{dimensionLabels[key]||key}} · {{statusLabels[check.status]||check.status}} · {{check.reason}}</p></details><EvidenceDetails data-analytics-location="CareerPage.EvidenceDetails.3" :data="state.view?.facts" title="规范化 Claim 与原始证据路径" /></section>

   <section v-if="state.material.lint.length" class="panel"><h2>材料风险检查 · {{state.material.label}}</h2><p v-for="(l,i) in state.material.lint" :key="i" class="note warning">{{l.code}} · {{l.message}}</p></section>
   <template v-for="g in groups" :key="g"><section class="panel"><h2>{{heading[g]}}</h2><article v-for="s in state.material.sections[g]" :key="s.section_id" class="builder-card" :data-testid="'career-'+g+'-'+s.section_id"><h3>{{s.title}}</h3><p class="note warning" v-if="s.source_type==='USER_UNVERIFIED_CLAIM'">当前为自由编辑文案，原机器引用不证明修改稿属实。</p><p class="career-text">{{s.text}}</p><details v-if="s.source_type==='USER_UNVERIFIED_CLAIM'"><summary v-track="{action:'career.original',placement:'CareerPage.control_24'}">对照机器原稿</summary><p class="career-text">{{s.safe_wording}}</p></details><p v-if="s.timing?.estimated_seconds" class="muted">按所选语速估计约 {{s.timing.estimated_seconds}} 秒；请实际试读。</p><details v-if="s.citations?.length"><summary v-track="{action:'career.citations',placement:'CareerPage.control_25'}">逐条事实引用</summary><div v-for="(cite,i) in s.citations" :key="i"><p>{{cite.text_span}}</p><EvidenceDetails data-analytics-location="CareerPage.EvidenceDetails.4" :data="cite" title="引用的 Claim / 原始路径" /></div></details>
    <details><summary v-track="{action:'career.inspector',placement:'CareerPage.control_26'}">Evidence Inspector · 来源 / 风险 / 追问</summary><p>安全措辞：{{s.safe_wording}}</p><ul><li v-for="risk in s.risk" :key="risk">{{risk}}</li><li v-for="q in s.possible_follow_up" :key="q">追问：{{q}}</li></ul><div v-for="c in resumeClaims(s.claim_ids)" :key="c.claim_id"><p>{{c.claim_id}} · {{c.claim_text}} · {{c.source_type}}</p><EvidenceDetails data-analytics-location="CareerPage.EvidenceDetails.5" :data="c" title="Supporting Evidence" /></div></details>
    <div v-if="editKey===g+':'+s.section_id"><p class="muted">机器原稿：{{s.safe_wording||s.text}}</p><label>编辑文案<textarea v-track="{action:'careerpage.edit_start',placement:'CareerPage.material_editor',kind:'edit'}" v-model="editText" rows="6" /></label><p class="note">FACT 保持锁定。自由编辑会保存为文案草稿；与 Evidence 不一致的数字或结论会标记风险，不自动成为实验事实。</p><button v-track="{action:'career.edit',placement:'CareerPage.control_27',core:true,reason:(work.state.busy ? 'busy' : 'missing_input'),material:({case_study:'project',resume_ai:'resume',resume_general:'resume',interview:'interview'})[g]}" class="primary" :disabled="!editText.trim() || !!work.state.busy" @click="save(g,s)">保存文案新版本</button><button v-track="{action:'career.cancel_edit',placement:'CareerPage.control_28',material:({case_study:'project',resume_ai:'resume',resume_general:'resume',interview:'interview'})[g]}" class="text-button" @click="editKey=''">取消</button></div>
    <div v-else class="button-row"><button v-track="{action:'career.begin_edit',placement:'CareerPage.control_29',material:({case_study:'project',resume_ai:'resume',resume_general:'resume',interview:'interview'})[g]}" class="secondary" :disabled="!!work.state.busy" @click="begin(g,s)">编辑文字</button><button v-track="{action:'career.regenerate',placement:'CareerPage.control_30',core:true,reason:('busy'),material:({case_study:'project',resume_ai:'resume',resume_general:'resume',interview:'interview'})[g]}" class="text-button" :disabled="!!work.state.busy" @click="career.regenerate(g,s.section_id)">从锁定 Evidence 重新生成此段</button></div>
   </article></section></template>
   <section v-if="state.tab==='Interview'" class="panel"><h2>Contribution Summary</h2><p v-for="c in state.material.contribution_summary" :key="c.owner">{{c.owner}}：{{c.text}}</p></section>
   <section v-if="state.tab==='Defense'" class="panel"><h2>项目追问 · {{state.material.defense.length}} 题</h2><details v-for="q in state.material.defense" :key="q.question_id" class="builder-card"><summary v-track="{action:'interview.question',placement:'CareerPage.control_31',material:'interview'}">{{q.pressure?'压力追问 · ':''}}{{q.category}} · {{q.question}}</summary><InterviewPractice data-analytics-location="CareerPage.InterviewPractice.6" :material-id="state.material.material_id" :question="q" /><details><summary v-track="{action:'interview.outline',placement:'CareerPage.control_32',material:'interview'}">查看参考回答提纲</summary><p class="career-text">{{q.suggested_answer_outline}}</p></details><h4>下一层追问</h4><p v-for="f in q.possible_follow_up" :key="f">{{f}}</p><h4>风险 / 限制</h4><ul><li v-for="r in q.risk" :key="r">{{r}}</li></ul><p v-for="m in q.missing_information" :key="m">{{m}}</p><EvidenceDetails data-analytics-location="CareerPage.EvidenceDetails.7" :data="{claim_ids:q.claim_ids,paths:q.supporting_evidence}" title="Supporting Evidence" /></details></section>
  </template>
 </template>
 </WorkspaceDrawer>
</template>
<style scoped>
dt{font-weight:700;margin-top:16px}dd{margin:6px 0;line-height:1.8}.career-tabs{margin:24px 0}.career-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9}.builder-card{margin:18px 0}fieldset{border:0;padding:0}details{margin:14px 0}summary{cursor:pointer}li{line-height:1.8;margin:8px 0}small{overflow-wrap:anywhere}
</style>
